insert into product_images (product_id, url, alt, sort_order) select id, '/products/inverter-dark.svg', 'Newcastle 5kW Hybrid Solar Inverter', 1 from products where slug = 'newcastle-5kw-hybrid-inverter' and not exists (select 1 from product_images pi join products pp on pp.id = pi.product_id where pp.slug = 'newcastle-5kw-hybrid-inverter' and pi.sort_order = 1);
insert into products (slug, sku, name, brand_id, category_id, short_description, description, highlights, specs, warranty, price, compare_at_price, status, is_featured, is_best_seller, is_new, installable, flash_deal_ends_at, rating_avg, rating_count, sold_count)
insert into product_images (product_id, url, alt, sort_order) select id, '/products/ess.svg', 'Newcastle 5KVA All-in-One ESS (10kWh)', 0 from products where slug = 'newcastle-5kva-all-in-one-ess' and not exists (select 1 from product_images pi join products pp on pp.id = pi.product_id where pp.slug = 'newcastle-5kva-all-in-one-ess' and pi.sort_order = 0);
insert into product_images (product_id, url, alt, sort_order) select id, '/products/ess-dark.svg', 'Newcastle 5KVA All-in-One ESS (10kWh)', 1 from products where slug = 'newcastle-5kva-all-in-one-ess' and not exists (select 1 from product_images pi join products pp on pp.id = pi.product_id where pp.slug = 'newcastle-5kva-all-in-one-ess' and pi.sort_order = 1);
insert into coupons (code, type, value, min_subtotal, max_discount) values ('WELCOME5', 'percent', 5, 100000, 50000) on conflict (code) do nothing;
insert into coupons (code, type, value, min_subtotal, max_discount) values ('COOL20K', 'fixed', 20000, 400000, null) on conflict (code) do nothing;
